SELECT ja.*, j.title AS job_title, j.department AS job_department, j.job_type AS job_type, j.min_salary AS job_min_salary, j.max_salary AS job_max_salary, j.city AS job_city, j.experience AS job_experience, j.education AS job_education, c.name AS company_name, c.logo AS company_logo, c.industry AS company_industry, u.username AS user_username, u.real_name AS user_real_name, u.phone AS user_phone, u.email AS user_email, u.avatar AS user_avatar, r.real_name AS resume_real_name, r.phone AS resume_phone, r.email AS resume_email, r.intention_position AS resume_intention_position, r.education AS resume_education, r.graduate_school AS resume_graduate_school, r.major AS resume_major, r.work_experience AS resume_work_experience, r.skills AS resume_skills FROM job_application ja LEFT JOIN job j ON ja.job_id = j.id LEFT JOIN company c ON ja.company_id = c.id LEFT JOIN user u ON ja.user_id = u.id LEFT JOIN resume r ON ja.resume_id = r.id WHERE ja.user_id = #{userId} AND ja.deleted = 0
AND ja.status = #{status}
ORDER BY ja.applied_at DESC LIMIT #{offset}, #{size}

SELECT ja.*, j.title AS job_title, j.department AS job_department, j.job_type AS job_type, j.min_salary AS job_min_salary, j.max_salary AS job_max_salary, j.city AS job_city, j.experience AS job_experience, j.education AS job_education, c.name AS company_name, c.logo AS company_logo, c.industry AS company_industry, u.username AS user_username, u.real_name AS user_real_name, u.phone AS user_phone, u.email AS user_email, u.avatar AS user_avatar, r.real_name AS resume_real_name, r.phone AS resume_phone, r.email AS resume_email, r.intention_position AS resume_intention_position, r.education AS resume_education, r.graduate_school AS resume_graduate_school, r.major AS resume_major, r.work_experience AS resume_work_experience, r.skills AS resume_skills FROM job_application ja LEFT JOIN job j ON ja.job_id = j.id LEFT JOIN company c ON ja.company_id = c.id LEFT JOIN user u ON ja.user_id = u.id LEFT JOIN resume r ON ja.resume_id = r.id WHERE ja.company_id = #{companyId} AND ja.deleted = 0
AND ja.status = #{status}
AND ( u.real_name LIKE CONCAT('%', #{keyword}, '%') OR j.title LIKE CONCAT('%', #{keyword}, '%') OR r.intention_position LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY ja.applied_at DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM job_application ja LEFT JOIN job j ON ja.job_id = j.id LEFT JOIN user u ON ja.user_id = u.id WHERE ja.company_id = #{companyId} AND ja.deleted = 0
AND ja.status = #{status}
AND ( u.real_name LIKE CONCAT('%', #{keyword}, '%') OR j.title LIKE CONCAT('%', #{keyword}, '%') )
